31: type driver18Sum struct { sum int64; reject bool; null bool }
32: func (s *driver18Sum) Step(_ *FunctionContext, args []driver.Value) error {
33: 	if s.reject { return errors.New("driver18 aggregate callback rejected") }
34: 	x, ok := args[0].(int64); if !ok { return errors.New("driver18 sum requires integer") }
35: 	s.sum += x; return nil
36: }
37: func (s *driver18Sum) WindowInverse(_ *FunctionContext, args []driver.Value) error {
38: 	x, ok := args[0].(int64); if !ok { return errors.New("driver18 inverse requires integer") }
39: 	s.sum -= x; return nil
40: }
41: func (s *driver18Sum) WindowValue(_ *FunctionContext) (driver.Value, error) {
42: 	if s.null { return nil, nil }; return s.sum, nil
43: }
