81: type driver18DB struct { db *sql.DB; conn *sql.Conn; ctx context.Context; cancel context.CancelFunc }
82: func driver18Open(t *testing.T, dsn string) *driver18DB {
83: 	t.Helper()
84: 	if driver18RegistrationError != nil { t.Fatal(driver18RegistrationError) }
85: 	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
86: 	db, err := sql.Open("sqlite", dsn); if err != nil { cancel(); t.Fatal(err) }
87: 	db.SetMaxOpenConns(2); db.SetMaxIdleConns(2)
88: 	c, err := db.Conn(ctx); if err != nil { db.Close(); cancel(); t.Fatal(err) }
89: 	f := &driver18DB{db: db, conn: c, ctx: ctx, cancel: cancel}
90: 	t.Cleanup(func() {
91: 		if err := c.Close(); err != nil { t.Errorf("connection close: %v", err) }
92: 		if err := db.Close(); err != nil { t.Errorf("database close: %v", err) }
93: 		cancel()
94: 	})
95: 	driver18Off(t, ctx, c)
96: 	return f
97: }
98: func driver18Off(t *testing.T, ctx context.Context, c *sql.Conn) {
99: 	t.Helper()
100: 	if _, err := c.ExecContext(ctx, "PRAGMA trusted_schema=OFF"); err != nil { t.Fatal(err) }
101: 	var got int
102: 	if err := c.QueryRowContext(ctx, "PRAGMA trusted_schema").Scan(&got); err != nil || got != 0 { t.Fatalf("trusted_schema got=%d err=%v", got, err) }
103: }
