111: func driver18Error(t *testing.T, err error, code int, text string) {
112: 	t.Helper(); var native *Error
113: 	if err == nil || !errors.As(err, &native) || native.Code() != code || !strings.Contains(err.Error(), text) {
114: 		t.Fatalf("expected SQLite code=%d containing %q; got %T %v", code, text, err, err)
115: 	}
