117: func driver18Oracle(t *testing.T, ctx context.Context, c *sql.Conn, name, typ string, arity, flags int) {
118: 	t.Helper()
119: 	rows, err := c.QueryContext(ctx, "SELECT name,builtin,type,enc,narg,flags FROM pragma_function_list WHERE name=?", name)
120: 	if err != nil { t.Fatal(err) }; defer func(){ if err := rows.Close(); err != nil { t.Error(err) } }()
121: 	count := 0
122: 	for rows.Next() {
123: 		var n, k, enc string; var builtin, na, fl int
124: 		if err := rows.Scan(&n, &builtin, &k, &enc, &na, &fl); err != nil { t.Fatal(err) }
125: 		count++
126: 		if n != name || builtin != 0 || k != typ || enc != "utf8" || na != arity || fl != flags { t.Fatalf("function_list %q builtin=%d type=%s enc=%s arity=%d flags=%d", n, builtin, k, enc, na, fl) }
127: 	}
128: 	if err := rows.Err(); err != nil { t.Fatal(err) }
129: 	if count != 1 { t.Fatalf("function_list %s count=%d", name, count) }
130: }
