162: func driver18AggregateView(t *testing.T, name string, window, allowed bool) {
163: 	f := driver18Open(t, ":memory:")
164: 	flags := 2048; if allowed { flags += 2097152 }
165: 	// Public MakeAggregate is installed with sqlite3_create_window_function;
166: 	// function_list.type is w even when the invocation uses aggregate syntax.
167: 	driver18Oracle(t, f.ctx, f.conn, name, "w", 1, flags)
168: 	f.exec(t, "CREATE TABLE data(x INTEGER)"); f.exec(t, "INSERT INTO data VALUES(1),(2),(3)")
169: 	f.integer(t, "SELECT "+name+"(x) FROM data", 6)
170: 	query := "SELECT "+name+"(x) AS value FROM data"
171: 	if window { query = "SELECT x,"+name+"(x) OVER(ORDER BY x ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS value FROM data" }
172: 	f.exec(t, "CREATE VIEW v AS "+query)
173: 	if !allowed {
174: 		rows, err := f.conn.QueryContext(f.ctx, "SELECT * FROM v")
175: 		if rows != nil { rows.Close() }
176: 		driver18Error(t, err, 1, "unsafe use of "+name+"()")
177: 		return
178: 	}
179: 	if !window { f.integer(t, "SELECT value FROM v", 6); return }
180: 	rows, err := f.conn.QueryContext(f.ctx, "SELECT value FROM v ORDER BY x")
181: 	if err != nil { t.Fatal(err) }; defer func(){ if err := rows.Close(); err != nil { t.Error(err) } }()
182: 	var got []int64
183: 	for rows.Next() { var x int64; if err := rows.Scan(&x); err != nil { t.Fatal(err) }; got=append(got,x) }
184: 	if err := rows.Err(); err != nil { t.Fatal(err) }
185: 	if !reflect.DeepEqual(got, []int64{1,3,5}) { t.Fatalf("moving sum=%v", got) }
